            batch_size=batch_size, 
            sampler=sampler,
            num_workers=num_workers,
            pin_memory=False
        )
    else:
        dataloader = DataLoader(
            dataset, 
            batch_size=batch_size, 
            shuffle=shuffle,
            num_workers=num_workers,
            pin_memory=False
        )

